const item = $input.first();
const names = Object.keys(item.binary || {});
const fail = (text) => [{ json: { ok: false, title: 'Hintergrund nicht geaendert', message: text } }];
if (names.length === 0) return fail('Es wurde kein Bild hochgeladen.');
const buffer = await this.helpers.getBinaryDataBuffer(0, names[0]);
const png = buffer.length > 8 && buffer.subarray(0, 8).toString('hex') === '89504e470d0a1a0a';
const jpeg = buffer.length > 3 && buffer.subarray(0, 3).toString('hex') === 'ffd8ff';
if (!png && !jpeg) return fail('Das Bild muss eine PNG- oder JPG-Datei sein.');
if (buffer.length > 4 * 1024 * 1024) return fail('Das Bild ist groesser als 4 MB. Bitte verkleinern (empfohlen: 2048 x 2732 Pixel).');
return [{ json: { ok: true, b64: buffer.toString('base64'), bytes: buffer.length, type: png ? 'PNG' : 'JPG' } }];

const cfg = {
  nanomdmUrl: 'http://mdm-nanomdm.mdm.svc.cluster.local:9000',
  depserverUrl: 'http://mdm-depserver.mdm.svc.cluster.local:9001',
  scepUrl: 'http://mdm-scep.mdm.svc.cluster.local:8080',
  publicHost: 'mdm-prod.pke-lab.de',
  depName: 'capulus',
  ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
  ntfyTopic: 'Home-Lab-MDM',
  vmUrl: 'http://vmsingle-monitoring-victoria-metrics-k8s-stack.monitoring.svc.cluster.local:8428',
  n8nUrl: 'https://n8n.prod.homeserver'
};
return [{ json: cfg }];

const sent = $('Befehle bauen').all().map((item) => item.json).filter((row) => !row.skip);
return $input.all().map((response, index) => {
  const source = sent[index];
  const body = response.json.body || {};
  const queued = body.command_uuid === source.command_uuid;
  const results = Object.values(body.status || {});
  const pushError = results.map((entry) => entry.push_error).filter(Boolean).join('; ');
  const detail = queued ? pushError : String(response.json.statusCode || response.json.error || 'keine Antwort');
  return { json: { enrollment_id: source.enrollment_id, profile_name: source.profile_name, command_uuid: source.command_uuid, ok: queued ? 'yes' : 'no', detail } };
});

const image = $('Bild pruefen').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
const failed = rows.filter((row) => row.state === 'failed');
let text = 'Neues Bild (' + image.type + ', ' + Math.round(image.bytes / 1024) + ' KB) gespeichert. ';
text += rows.length === 0 ? 'Es ist noch kein iPad angemeldet, neue iPads bekommen das Bild bei der Anmeldung.' : (rows.length - failed.length) + ' von ' + rows.length + ' iPad(s) haben den Befehl erhalten' + (failed.length > 0 ? ', ' + failed.length + ' fehlgeschlagen' : '') + '. Der Hintergrund wirkt nur auf beaufsichtigten iPads.';
return [{ json: { title: failed.length > 0 ? 'Hintergrund mit Fehlern gesendet' : 'Hintergrund gesendet', message: text, priority: failed.length > 0 ? 'high' : 'default' } }];
